[CmdletBinding()]
param(
    [Parameter(Mandatory=$true)][string]$ProjectPath,
    [Parameter(Mandatory=$true)][string]$VerificationRoot,
    [Parameter(Mandatory=$true)][string]$PilotPlanPath,
    [Parameter(Mandatory=$true)][string]$ProvenancePath,
    [Parameter(Mandatory=$true)][string]$TelemetryResultPath,
    [switch]$BindingSmokeOnly
)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
if([string]::IsNullOrWhiteSpace($ProjectPath)-or-not[IO.Path]::IsPathRooted($ProjectPath)){throw 'PR1B v3 validation-only audit requires an explicit absolute ProjectPath.'};$ProjectPath=[IO.Path]::GetFullPath($ProjectPath)
if($BindingSmokeOnly){Write-Output("BINDING-SMOKE-PASSED|Run-Gate13RPR1BValidationOnlyPrePilotAuditV3|$ProjectPath");exit 0}
$VerificationRoot=[IO.Path]::GetFullPath($VerificationRoot);$PilotPlanPath=[IO.Path]::GetFullPath($PilotPlanPath);$ProvenancePath=[IO.Path]::GetFullPath($ProvenancePath);$TelemetryResultPath=[IO.Path]::GetFullPath($TelemetryResultPath)
Import-Module (Join-Path $ProjectPath 'Research\Gate13RPR1BOrderEffectPreparationV3.psm1') -Force
$plan=Read-Gate13RPR1BV3Json $PilotPlanPath;$provenance=Read-Gate13RPR1BV3Json $ProvenancePath;$errors=New-Object Collections.Generic.List[string];$checks=New-Object Collections.Generic.List[object]
function Add-Check([string]$Id,[bool]$Passed,[string]$Detail){$script:checks.Add([pscustomobject][ordered]@{id=$Id;passed=$Passed;detail=$Detail});if(-not$Passed){$script:errors.Add("$Id`: $Detail")}}
$summaries=[ordered]@{
 static=Join-Path $VerificationRoot 'StaticUnit\summary.json';compile=Join-Path $VerificationRoot 'Compile\summary.json';pathSafe=$VerificationRoot+'\PathSafeAtomicSelfTest.summary.json';memoryPolicy=$VerificationRoot+'\MemoryPolicySelfTest.summary.json';telemetry=Join-Path $VerificationRoot 'TelemetryProbe\v3.summary.json';positiveNegative=Join-Path $VerificationRoot 'BlockVerification\summary.json';additional=Join-Path $VerificationRoot 'BlockVerificationAdditional\summary.json'
}
foreach($key in $summaries.Keys){$path=$summaries[$key];$present=Test-Path -LiteralPath $path -PathType Leaf;$passed=$present-and((Read-Gate13RPR1BV3Json $path).passed-eq$true);Add-Check ("upstream-$key") $passed $path}
$telemetry=if(Test-Path $TelemetryResultPath){Read-Gate13RPR1BV3Json $TelemetryResultPath}else{$null};Add-Check 'telemetry-v2-positive-crosscheck' ($null-ne$telemetry-and[string]$telemetry.resultKind-eq'gate13r-pr1b-v2-native-telemetry-probe-result-v1'-and$telemetry.passed-eq$true-and[long]$telemetry.nativeBefore.workingSetBytes-gt0-and[long]$telemetry.nativeBefore.privateMemoryBytes-gt0-and[long]$telemetry.externalQuery.workingSetBytes-gt0-and[long]$telemetry.externalQuery.privateMemoryBytes-gt0) $TelemetryResultPath
$pathSafeResult=Join-Path $VerificationRoot 'PathSafeAtomicSelfTest\path-safe-atomic-self-test.json';$pathSafe=if(Test-Path $pathSafeResult){Read-Gate13RPR1BV3Json $pathSafeResult}else{$null};Add-Check 'pathsafe-v3-boundaries' ($null-ne$pathSafe-and[string]$pathSafe.summaryKind-eq'gate13r-pr1b-v3-path-safe-atomic-persistence-self-test-v1'-and$pathSafe.passed-eq$true-and[int]$pathSafe.testCount-eq[int]$pathSafe.passedTestCount-and[int]$pathSafe.residualOwnedTemporaryFileCount-eq0) $pathSafeResult
foreach($binding in @($provenance.boundFiles)){$path=Join-Path $ProjectPath ([string]$binding.relativePath).Replace('/','\');Add-Check ('hash-'+([string]$binding.relativePath).Replace('/','_').Replace('.','_')) ((Test-Path $path)-and(Get-Gate13RPR1BV3LowerSha256 $path)-eq[string]$binding.sha256) ([string]$binding.relativePath)}
$prewritePath=Join-Path $ProjectPath 'Research\Gate13R_PR1B_v2_PreWrite_Preservation_Audit.v1.json';$prewrite=Read-Gate13RPR1BV3Json $prewritePath
foreach($frozen in @($prewrite.frozenReferences)){$path=Join-Path $ProjectPath ([string]$frozen.relativePath).Replace('/','\');Add-Check ('frozen-'+([string]$frozen.relativePath).Replace('/','_').Replace('.','_')) ((Test-Path $path)-and(Get-Gate13RPR1BV3LowerSha256 $path)-eq[string]$frozen.sha256) ([string]$frozen.relativePath)}
$attempt1Root=Join-Path $ProjectPath ([string]$prewrite.attempt1.rootRelativePath).Replace('/','\');$attempt1Files=@(Get-ChildItem -LiteralPath $attempt1Root -Recurse -File -Force);$attempt1Bytes=[long](($attempt1Files|Measure-Object Length -Sum).Sum);Add-Check 'attempt1-root-inventory-unchanged' ($attempt1Files.Count-eq[int]$prewrite.attempt1.fileCount-and$attempt1Bytes-eq[long]$prewrite.attempt1.rawBytes) "files=$($attempt1Files.Count) bytes=$attempt1Bytes"
try{Assert-Gate13RPR1BV3PlanIdentity $plan;$campaigns=@(Get-Gate13RPR1BV3Campaigns -ProjectPath $ProjectPath -Plan $plan);$measured=@(Get-Gate13RPR1BV3ProcessSchedule -Plan $plan -Campaigns $campaigns -AnalysisRole measured-non-formal-pilot);$warmup=@(Get-Gate13RPR1BV3ProcessSchedule -Plan $plan -Campaigns $campaigns -AnalysisRole excluded-warmup);$schedule=Test-Gate13RPR1BV3Schedule -Plan $plan -Measured $measured -Warmup $warmup;Add-Check 'schedule-deterministic-regeneration' ($schedule.passed-eq$true) (($schedule.errors)-join'; ')}catch{Add-Check 'schedule-deterministic-regeneration' $false $_.Exception.Message}
function Get-TreeIdentity([string]$Path){$treeRoot=[IO.Path]::GetFullPath($Path).TrimEnd('\');$files=@(Get-ChildItem -LiteralPath $treeRoot -Recurse -File -Force|Sort-Object FullName);$rows=@($files|ForEach-Object{$relative=$_.FullName.Substring($treeRoot.Length).TrimStart('\').Replace('\','/');"$relative`t$($_.Length)`t$(Get-Gate13RPR1BV3LowerSha256 $_.FullName)"});$sha=[Security.Cryptography.SHA256]::Create();try{$treeSha=([BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($rows-join"`n")))).Replace('-','').ToLowerInvariant()}finally{$sha.Dispose()};[pscustomobject][ordered]@{fileCount=$files.Count;rawBytes=[long](($files|Measure-Object Length -Sum).Sum);treeSha256=$treeSha}}
foreach($frozenTree in @(
 [pscustomobject]@{path='Research\PilotRuns\Gate12R_ProcessReuse_5pct\v6-gate13r-pr1b-order-effect-memory-v2';files=49;bytes=1955414;sha='85a3fba48ae687acaa04b7b1f91afe0dc115f6efdde5bcaa4bbffa50e9139557'},
 [pscustomobject]@{path='Research\Verification\Gate12R_ProcessReuse_5pct\v9-gate13r-pr1b-order-effect-memory-v2';files=20;bytes=176860;sha='5911830b100269a993a6b15194dac2ac18d2a3dc69ad677ce0005c830a047a74'},
 [pscustomobject]@{path='Research\Verification\Gate12R_ProcessReuse_5pct\v10-gate13r-pr1b-order-effect-memory-v2';files=39;bytes=275071;sha='5d20fbea2e6e734c9feddc2ed199a365bc307caac1a4b2cef3bb680cfebb2d44'},
 [pscustomobject]@{path='Research\Verification\Gate12R_ProcessReuse_5pct\v11-gate13r-pr1b-order-effect-memory-v2';files=244;bytes=6057665;sha='d819eb685a119175a5b1e362e7ac14997ff27b6f6696d109a6dd0202546b8d5b'}
)){$identity=Get-TreeIdentity (Join-Path $ProjectPath $frozenTree.path);Add-Check ('frozen-tree-'+([IO.Path]::GetFileName($frozenTree.path))) ($identity.fileCount-eq$frozenTree.files-and$identity.rawBytes-eq$frozenTree.bytes-and$identity.treeSha256-eq$frozenTree.sha) ($identity|ConvertTo-Json -Compress)}
$positiveRoot=Join-Path $VerificationRoot 'BlockVerification\positive-mirrored';$evaluations=@(Get-ChildItem -LiteralPath $positiveRoot -Recurse -Filter 'memory-gate-evaluation.json' -File -ErrorAction SilentlyContinue);Add-Check 'positive-memory-evaluation-count' ($evaluations.Count-eq8) "count=$($evaluations.Count)"
$negativeRoot=Join-Path $VerificationRoot 'BlockVerification\negative-fail-closed\per-agent';$negativeFailure=if(Test-Path (Join-Path $negativeRoot 'block-failure.json')){Read-Gate13RPR1BV3Json (Join-Path $negativeRoot 'block-failure.json')}else{$null};$negativeCheckpoint=if(Test-Path (Join-Path $negativeRoot 'block-checkpoint.json')){Read-Gate13RPR1BV3Json (Join-Path $negativeRoot 'block-checkpoint.json')}else{$null};Add-Check 'negative-fail-closed-terminal' ($null-ne$negativeFailure-and$null-ne$negativeCheckpoint-and[int]$negativeFailure.completedSampleCount-eq1-and[string]$negativeCheckpoint.status-eq'failed-no-auto-retry') $negativeRoot
$pilotRoot=Join-Path $ProjectPath ([string]$plan.paths.pilotRootRelativePath).Replace('/','\');$formalRoot=Join-Path $ProjectPath ([string]$plan.paths.reservedFormalRootRelativePath).Replace('/','\')
Add-Check 'pilot-root-absent' (-not(Test-Path $pilotRoot)) $pilotRoot;Add-Check 'formal-root-absent' (-not(Test-Path $formalRoot)) $formalRoot;Add-Check 'unity-closed' (@(Get-Process -Name Unity -ErrorAction SilentlyContinue).Count-eq0) 'No Unity process may remain.';Add-Check 'unity-lock-absent' (-not(Test-Path (Join-Path $ProjectPath 'Temp\UnityLockfile'))) 'Unity project lock must be absent.'
$summary=[ordered]@{schemaVersion=3;summaryKind='gate13r-pr1b-v3-pathsafe-validation-only-pre-pilot-audit-v1';savedAtUtc=[DateTime]::UtcNow.ToString('o');pilotPlanSha256=Get-Gate13RPR1BV3LowerSha256 $PilotPlanPath;provenanceSha256=Get-Gate13RPR1BV3LowerSha256 $ProvenancePath;telemetryResultSha256=Get-Gate13RPR1BV3LowerSha256 $TelemetryResultPath;checkCount=$checks.Count;passedCheckCount=@($checks|Where-Object passed).Count;checks=$checks.ToArray();errors=$errors.ToArray();pilotExecutionAuthorized=$errors.Count-eq0;formalCampaign=$false;gate13rFormalAuthorized=$false;gate14rAuthorized=$false;passed=$errors.Count-eq0}
Write-Gate13RPR1BV3AtomicUtf8NoBomJson -Path (Join-Path $VerificationRoot 'ValidationOnlyPrePilotAudit.summary.json') -Value $summary -Depth 50
if($errors.Count){Write-Error("PR1B v3 validation-only pre-pilot audit failed: "+($errors-join'; '));exit 1};Write-Host 'PR1B v3 validation-only pre-pilot audit passed.' -ForegroundColor Green;exit 0


